// Captions — owner: Module D (PLAN.md §6.5 on-device sponsor detection; `captionTracks`, §5.4).
//
// Pure pieces that turn the page's caption tracks into timed text the model can read:
//   1. decode the `captionTracks` reply (`{videoId, tracks: [{baseUrl, languageCode, kind, name}],
//      client?: {clientVersion, signatureTimestamp} | null}`; `client` added 2026-11-25, see
//      InnertubeCaptions.swift for why);
//   2. choose a track (v1: English only; a manual track beats auto-generated `asr`);
//   3. build the json3 URL (`baseUrl` with `fmt=json3`, checked anonymous HTTP 200 on 2026-11-25);
//   4. parse json3 into sorted, non-empty cues.
// json3 shape (fixture TestVectors/transcripts/2026-11-25-timedtext-WWfjoGZmrTo.json):
// `{wireMagic, events: [{tStartMs, dDurationMs, segs: [{utf8, tOffsetMs?}]?, aAppend?}]}`. Some
// events have no `segs` (window setup) or only "\n" (line breaks in rolling auto-captions).

import Foundation

public enum Captions {
    // MARK: Caption tracks

    public struct CaptionTrack: Codable, Equatable, Sendable {
        public var baseUrl: String
        public var languageCode: String
        /// `"asr"` for auto-generated captions, else `""`.
        public var kind: String
        public var name: String

        public init(baseUrl: String, languageCode: String, kind: String = "", name: String = "") {
            self.baseUrl = baseUrl
            self.languageCode = languageCode
            self.kind = kind
            self.name = name
        }

        public var isAutoGenerated: Bool { kind == "asr" }
        public var isEnglish: Bool { languageCode.lowercased().hasPrefix("en") }
    }

    /// The `captionTracks` command's reply.
    public struct CaptionTracksReply: Equatable, Sendable {
        public var videoId: String?
        public var tracks: [CaptionTrack]
        /// The page's MWEB client values (for a /player request), when the page has them.
        public var client: InnertubeClient?

        public init(videoId: String?, tracks: [CaptionTrack], client: InnertubeClient? = nil) {
            self.videoId = videoId
            self.tracks = tracks
            self.client = client
        }
    }

    public enum DecodeError: Error, Equatable, Sendable {
        case malformed
    }

    /// Decodes the reply JSON. A track without a string `baseUrl` or `languageCode` is dropped;
    /// a missing `kind`/`name` reads as "". A missing or malformed `client` reads as nil. A reply
    /// that isn't an object throws.
    public static func captionTracks(fromJSON json: String) throws -> CaptionTracksReply {
        guard let object = try? JSONSerialization.jsonObject(with: Data(json.utf8)) as? [String: Any]
        else { throw DecodeError.malformed }
        let videoId = object["videoId"] as? String
        let rawTracks = object["tracks"] as? [Any] ?? []
        let tracks = rawTracks.compactMap { raw -> CaptionTrack? in
            guard let t = raw as? [String: Any],
                  let baseUrl = t["baseUrl"] as? String, !baseUrl.isEmpty,
                  let languageCode = t["languageCode"] as? String
            else { return nil }
            return CaptionTrack(baseUrl: baseUrl, languageCode: languageCode,
                                kind: t["kind"] as? String ?? "", name: t["name"] as? String ?? "")
        }
        var client: InnertubeClient?
        if let c = object["client"] as? [String: Any], let version = c["clientVersion"] as? String,
           InnertubeClient.isValidVersion(version), let sts = c["signatureTimestamp"] as? Int, sts > 0 {
            client = InnertubeClient(clientVersion: version, signatureTimestamp: sts)
        }
        return CaptionTracksReply(videoId: videoId, tracks: tracks, client: client)
    }

    public enum TrackChoice: Equatable, Sendable {
        case track(CaptionTrack)
        /// Why no track was chosen (for the Debug log).
        case none(reason: String)
    }

    /// v1 reads English only: the first manual English track, else the first auto-generated
    /// English one, else none (with the languages that were offered).
    public static func chooseTrack(_ tracks: [CaptionTrack]) -> TrackChoice {
        if tracks.isEmpty { return .none(reason: "no caption tracks") }
        if let manual = tracks.first(where: { $0.isEnglish && !$0.isAutoGenerated }) { return .track(manual) }
        if let asr = tracks.first(where: { $0.isEnglish && $0.isAutoGenerated }) { return .track(asr) }
        let languages = tracks.map { $0.isAutoGenerated ? $0.languageCode + " (auto)" : $0.languageCode }
        return .none(reason: "no English track (offered: \(languages.joined(separator: ", ")))")
    }

    /// `baseUrl` with `fmt=json3` (replacing any `fmt`). nil unless it is an https URL on
    /// youtube.com (or a subdomain) with path `/api/timedtext`, so a bad page reply can't make us
    /// fetch anything else. The rest of the query (signed parameters) is kept byte for byte.
    public static func json3URL(baseUrl: String) -> URL? {
        guard var components = URLComponents(string: baseUrl),
              components.scheme?.lowercased() == "https",
              let host = components.host?.lowercased(),
              host == "youtube.com" || host.hasSuffix(".youtube.com"),
              components.path == "/api/timedtext"
        else { return nil }
        var items = (components.percentEncodedQueryItems ?? []).filter { $0.name != "fmt" }
        items.append(URLQueryItem(name: "fmt", value: "json3"))
        components.percentEncodedQueryItems = items
        return components.url
    }

    // MARK: json3

    /// One caption line, in seconds of the video.
    public struct Cue: Equatable, Sendable {
        public var start: Double
        public var end: Double
        public var text: String

        public init(start: Double, end: Double, text: String) {
            self.start = start
            self.end = end
            self.text = text
        }
    }

    /// Cues from a json3 body: text joined from `segs[].utf8`, HTML entities decoded, whitespace
    /// collapsed; empty cues dropped; sorted by start. Auto-captions roll (each event stays on
    /// screen until the one after next), so a cue's `end` is `min(start + duration, next start)`:
    /// the time its words are spoken, not the time it is displayed. Throws if the body isn't json3.
    public static func cues(fromJSON3 data: Data) throws -> [Cue] {
        let body: JSON3
        do {
            body = try JSONDecoder().decode(JSON3.self, from: data)
        } catch {
            throw DecodeError.malformed
        }
        var raw: [(start: Double, duration: Double?, text: String)] = []
        for event in body.events ?? [] {
            guard let startMs = event.tStartMs, startMs.isFinite, startMs >= 0, let segs = event.segs else { continue }
            let text = normalize(segs.compactMap(\.utf8).joined())
            guard !text.isEmpty else { continue }
            let duration = event.dDurationMs.flatMap { $0.isFinite && $0 >= 0 ? $0 / 1000 : nil }
            raw.append((startMs / 1000, duration, text))
        }
        raw.sort { $0.start < $1.start }
        var cues: [Cue] = []
        cues.reserveCapacity(raw.count)
        for (index, item) in raw.enumerated() {
            let next = raw[(index + 1)...].first(where: { $0.start > item.start })?.start
            var end = item.duration.map { item.start + $0 } ?? next ?? item.start + 2
            if let next { end = min(end, next) }
            cues.append(Cue(start: item.start, end: max(end, item.start), text: item.text))
        }
        return cues
    }

    /// Entities decoded, newlines and runs of whitespace collapsed to one space, trimmed.
    static func normalize(_ text: String) -> String {
        decodeEntities(text)
            .split(whereSeparator: { $0.isWhitespace })
            .joined(separator: " ")
    }

    /// Decodes `&amp; &lt; &gt; &quot; &apos; &#39; &nbsp;` and numeric `&#N;`/`&#xH;` entities.
    /// Anything else (including a bare `&`) is kept as written. (Hand-rolled: Linux Foundation
    /// has no HTML-attributed-string decoding.)
    static func decodeEntities(_ text: String) -> String {
        guard text.contains("&") else { return text }
        let named: [Substring: String] = ["amp": "&", "lt": "<", "gt": ">", "quot": "\"", "apos": "'", "nbsp": " "]
        var out = ""
        var rest = Substring(text)
        while let amp = rest.firstIndex(of: "&") {
            out += rest[..<amp]
            let afterAmp = rest.index(after: amp)
            if let semi = rest[afterAmp...].prefix(10).firstIndex(of: ";") {
                let name = rest[afterAmp..<semi]
                var decoded: String?
                if let value = named[name] {
                    decoded = value
                } else if name.hasPrefix("#x") || name.hasPrefix("#X") {
                    decoded = UInt32(name.dropFirst(2), radix: 16).flatMap(Unicode.Scalar.init).map { String(Character($0)) }
                } else if name.hasPrefix("#") {
                    decoded = UInt32(name.dropFirst()).flatMap(Unicode.Scalar.init).map { String(Character($0)) }
                }
                if let decoded {
                    out += decoded
                    rest = rest[rest.index(after: semi)...]
                    continue
                }
            }
            out += "&"
            rest = rest[afterAmp...]
        }
        out += rest
        return out
    }

    private struct JSON3: Decodable {
        let events: [Event]?
    }

    private struct Event: Decodable {
        let tStartMs: Double?
        let dDurationMs: Double?
        let segs: [Seg]?

        init(from decoder: any Decoder) throws {
            let c = try decoder.container(keyedBy: CodingKeys.self)
            tStartMs = try? c.decodeIfPresent(Double.self, forKey: .tStartMs)
            dDurationMs = try? c.decodeIfPresent(Double.self, forKey: .dDurationMs)
            segs = try? c.decodeIfPresent([Seg].self, forKey: .segs)
        }

        enum CodingKeys: String, CodingKey { case tStartMs, dDurationMs, segs }
    }

    private struct Seg: Decodable {
        let utf8: String?

        init(from decoder: any Decoder) throws {
            let c = try decoder.container(keyedBy: CodingKeys.self)
            utf8 = try? c.decodeIfPresent(String.self, forKey: .utf8)
        }

        enum CodingKeys: String, CodingKey { case utf8 }
    }
}
